// StatusString returns a mnemonic for the documented status codes, otherwise the
// hex value.
func StatusString(status uint32) string {
	switch status {
	case StatusSuccess:
		return "ERROR_SUCCESS"
	case ErrorFileNotFound:
		return "ERROR_FILE_NOT_FOUND"
	case ErrorPathNotFound:
		return "ERROR_PATH_NOT_FOUND"
	case ErrorAccessDenied:
		return "ERROR_ACCESS_DENIED"
	case ErrorInvalidHandle:
		return "ERROR_INVALID_HANDLE"
	case ErrorNotEnoughMemory:
		return "ERROR_NOT_ENOUGH_MEMORY"
	case ErrorInvalidParameter:
		return "ERROR_INVALID_PARAMETER"
	case ErrorInsufficientBuffer:
		return "ERROR_INSUFFICIENT_BUFFER"
	case ErrorNoMoreItems:
		return "ERROR_NO_MORE_ITEMS"
	case ErrorTimeout:
		return "ERROR_TIMEOUT"
	case ErrorNotFound:
		return "ERROR_NOT_FOUND"
	case ErrorEvtInvalidChannelPath:
		return "ERROR_EVT_INVALID_CHANNEL_PATH"
	case ErrorEvtInvalidQuery:
		return "ERROR_EVT_INVALID_QUERY"
	case ErrorEvtPublisherMetadataNotFound:
		return "ERROR_EVT_PUBLISHER_METADATA_NOT_FOUND"
	case ErrorEvtEventTemplateNotFound:
		return "ERROR_EVT_EVENT_TEMPLATE_NOT_FOUND"
	case ErrorEvtInvalidPublisherName:
		return "ERROR_EVT_INVALID_PUBLISHER_NAME"
	case ErrorEvtInvalidEventData:
		return "ERROR_EVT_INVALID_EVENT_DATA"
	case ErrorEvtChannelNotFound:
		return "ERROR_EVT_CHANNEL_NOT_FOUND"
	case ErrorEvtMalformedXmlText:
		return "ERROR_EVT_MALFORMED_XML_TEXT"
	case ErrorEvtQueryResultStale:
		return "ERROR_EVT_QUERY_RESULT_STALE"
	case ErrorEvtMessageNotFound:
		return "ERROR_EVT_MESSAGE_NOT_FOUND"
	case ErrorEvtMessageIDNotFound:
		return "ERROR_EVT_MESSAGE_ID_NOT_FOUND"
	case ErrorEvtUnresolvedValueInsert:
		return "ERROR_EVT_UNRESOLVED_VALUE_INSERT"
	default:
		return fmt.Sprintf("0x%08x", status)
	}
}

